  }
  .panel h2 {
    font-size: 1rem;
    margin-bottom: 10px;
    color: #fff;
    border-bottom: 1px solid #333;
    padding-bottom: 6px;
  }
  .status-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 5px 0;
    font-size: 0.85rem;
  }
  .status-label { color: #aaa; }
  .status-value {
    font-weight: bold;
